import type { SourceLink } from "../../types.js";
import type { RefreshCtx, Refreshed, SeedInput } from "./refreshers-part1.js";
import { assemble, dot, fresh, LiveMiningError, requireNum } from "./refreshers-part1.js";
import type { SourceApi, SourceDoc } from "./sources.js";

/** Path 3: Spain Vox seats — live Electografía/Data10 tracking page. */
export async function refreshEsVox(seed: SeedInput, api: SourceApi, ctx: RefreshCtx): Promise<Refreshed> {
  const [trackingDoc] = await Promise.all([fresh(api, seed.sources.electografica, "electografica", ctx)]);
  const body = trackingDoc.body;
  const voxSeatsM = body.match(/Vox\s*\n?s*[uU]i?[rp][td]?[aía]*[^]*?(?:alcanzaría|alcanzaría una|subiría una?|alcanza(?:ría)?(?: una)?)[^]*?(\d{1,3})\s*(?:diputad|escañ|representante)/);
  const simpleSeats = body.match(/Vox\s*\n\s*\n?VOX[^]*?\n(\d{2})\n/) ?? body.match(/Vox subiría una décima, hasta el (\d{2},\d) %, y alcanzaría (\d{1,3}) diputados/);
  const voteShareM = body.match(/Vox\s*\n?\s*subiría una décima, hasta el (\d{1,2},\d) %/) ?? body.match(/hasta el (\d{1,2},\d) %, y alcanzaría/);
  const seatsFromText = simpleSeats?.[2] ?? voxSeatsM?.[1];
  if (!seatsFromText || !voteShareM) throw new LiveMiningError("Electografía page did not parse");
  const seats = requireNum(seatsFromText, "Vox projected seats");
  const share = requireNum(voteShareM[1], "Vox national vote share");

  const thr = Number(seed.market.thresholdSeats);
  const sd = Number(seed.assumptions.seatEstimateSd);

  const figures = [
    `Live Data10 tracking (Electografía, updated for the 29 Nov 2026 general election): Vox at ${share.toFixed(1)}% nationally and ${seats} projected Congress seats`,
    `Same tracker's other parties: PP ~131-133, PSOE ~113-117, Frente Amplio ~9 — Vox is the third bloc`,
    `Seat bar: ${thr} seats; the tracker's own projection sits ${seats >= thr ? "+" : ""}${seats - thr} seats relative to it`,
  ];
  const headline =
    `Live provincial tracker (Data10 via Electografía, fetched ${ctx.now.toISOString().slice(0, 10)}): Vox polls at ${share.toFixed(1)}% nationally ` +
    `and projects to ${seats} Congress of Deputies seats — ${seats >= thr ? `above` : `below`} the ${thr}-seat bar — using its own D'Hondt-style provincial seat model.`;

  const links: SourceLink[] = [
    {
      url: trackingDoc.url,
      label: "Electografía/Data10 26N general-election tracking (Vox: vote share + seats)",
      lang: "es",
      access: "scraped",
      expect: [voteShareM[1], seatsFromText],
    },
  ];
  return assemble(
    seed,
    [trackingDoc],
    headline,
    figures,
    [
      `Electografía tracking page (static HTML, ES): Data10 daily seat/vote projection for the 29 Nov 2026 general election; Vox ${dot(voteShareM[1])}% / ${seats} seats.`,
    ],
    links,
    {
      kind: "seat_threshold",
      params: {
        party: "Vox",
        source: "Electografía/Data10 tracking page",
        sourceSeatEstimate: seats,
        sourceVoteSharePct: share,
        thresholdSeats: thr,
        estimateSd: sd,
      },
    },
    [`Seat-projection error sd (${sd} seats) is a stated model assumption`],
  );
}

/** Path 2: IESG ballot state for draft-ietf-mpls-mna-ioam. */
export async function refreshIetfBallot(seed: SeedInput, api: SourceApi, ctx: RefreshCtx): Promise<Refreshed> {
  const [ballotDoc] = await Promise.all([fresh(api, seed.sources.ballot, "ballot", ctx)]);
  const body = ballotDoc.body;
  const neededM = body.match(/Needs (\d+) more YES or NO OBJECTION positions to pass/);
  const yesCount = (body.match(/Yes\b/g) ?? []).length - (body.match(/Yes\s*$/gm) ?? []).length;
  const yesM = body.match(/\bYes\b\s*\n\s*([A-ZÉ][\w'. -]+)\n/);
  const positionsTotalM = [...body.matchAll(/(Jim Guichard|Andy Newton|Charles Eckel|Christopher Inacio|Deb Cooley|Éric Vyncke|Gorry Fairhurst|Gunter Van de Velde|Jen Linkova|Ketan Talaulikar|Mahesh Jethanandani|Mike Bishop|Mohamed Boucadair|Roman Danyliw)/g)];
  const noRecordM = [...body.match(/No Record/g) ?? []].length;
  if (!neededM) throw new LiveMiningError("Datatracker ballot page did not parse (no 'needs N more' text)");
  const needed = requireNum(neededM[1], "needed to pass");
  const positionsTotal = new Set(positionsTotalM.map((m) => m[1])).size;
  if (positionsTotal === 0) throw new LiveMiningError("no IESG positions parsed from the ballot page");
  const discussCount = (body.match(/\bDISCUSS\b/g) ?? []).length;
  const recordedYes = yesCount > 0 ? yesCount : yesM ? 1 : 0;

  const withDiscuss = Number(seed.assumptions.comparableDraftsWithDiscuss);
  const similarDrafts = Number(seed.assumptions.comparableDrafts);

  const figures = [
    `Live IESG ballot for draft-ietf-mpls-mna-ioam-18 (Datatracker, fetched ${ctx.now.toISOString().slice(0, 10)}): ${discussCount === 0 ? "no DISCUSS positions recorded yet" : `${discussCount} DISCUSS position(s) on record`}; ${positionsTotal} IESG members on the ballot; "Needs ${needed} more YES or NO OBJECTION positions to pass"`,
    `Positions recorded so far: ${recordedYes} Yes (${yesM?.[1].trim() ?? "-"}), the other ${positionsTotal - recordedYes} members No Record`,
    `Model: comparable-draft base rate ${withDiscuss}/${similarDrafts} (stated assumption) attenuated by the ${(positionsTotal - recordedYes) / positionsTotal >= 0 ? (positionsTotal - recordedYes) : 0}/${positionsTotal} share of positions still unrecorded — every DISCUSS in this state lands before positions are recorded`,
  ];
  const headline =
    `The IESG ballot for draft-ietf-mpls-mna-ioam-18 was open at fetch with ${discussCount} DISCUSS positions on record and ${positionsTotal - recordedYes} of ` +
    `${positionsTotal} IESG members yet to record a position ("Needs ${needed} more YES or NO OBJECTION positions to pass") — ` +
    `${recordedYes} Yes so far (${yesM?.[1].trim() ?? "-"}).`;

  const links: SourceLink[] = [
    {
      url: ballotDoc.url,
      label: "IETF Datatracker: IESG evaluation record / ballot for draft-ietf-mpls-mna-ioam",
      lang: "en",
      access: "scraped",
      expect: [neededM[0].slice(0, 40)],
    },
  ];
  return assemble(
    seed,
    [ballotDoc],
    headline,
    figures,
    [
      `Datatracker ballot page (static HTML): IESG evaluation record for draft-ietf-mpls-mna-ioam-18; position list and "Needs ${needed} more..." summary.`,
    ],
    links,
    {
      kind: "ballot_flag_snapshot",
      params: {
        doc: "draft-ietf-mpls-mna-ioam-18",
        ballotStateText: `${discussCount} DISCUSS on record, ${positionsTotal - recordedYes}/${positionsTotal} positions unrecorded`,
        positionsRecorded: recordedYes,
        positionsTotal,
        neededToPass: needed,
        discussCount,
        similarDrafts,
        withDiscuss,
      },
    },
    [
      `Comparable MPLS-area draft set (${withDiscuss}/${similarDrafts} drew a DISCUSS) is a stated assumption, not a live fetch`,
    ],
  );
}

/** Path 2: FIDE WCC 2026 match — official factsheet + embedded ratings. */
export async function refreshFideMatch(seed: SeedInput, api: SourceApi, ctx: RefreshCtx): Promise<Refreshed> {
  const [fideDoc, ratingsDoc] = await Promise.all([
    fresh(api, seed.sources.fideNews, "fideNews", ctx),
    fresh(api, seed.sources.worldchess, "worldchess", ctx),
  ]);
  const fide = fideDoc.body;
  const scoreM = fide.match(/Match score: (\d+)[–-](\d+)/);
  const gameM = fide.match(/FACT SHEET – Game (\d+)/);
  const whiteM = fide.match(/FACT SHEET – Game \d+[^]*?White: ([A-Za-zÉé]+(?:\s[A-Za-z]+)*)/);
  const blackM = fide.match(/FACT SHEET – Game \d+[^]*?Black: ([A-Za-zÉé]+(?:\s[A-Za-z]+)*)/);
  const nextWhiteM = fide.match(/will have the white pieces for the second time in the match tomorrow, when game (\d+) /);
  if (!scoreM || !gameM || !whiteM || !blackM) throw new LiveMiningError("FIDE factsheet did not parse");
  const scoreA = requireNum(scoreM[1], "Sindarov score");
  const scoreB = requireNum(scoreM[2], "Gukesh score");
  const gamesPlayed = requireNum(gameM[1], "games played");
  const whiteName = whiteM[1].trim();
  const blackName = blackM[1].trim();

  const ratingA = requireNum(ratingsDoc.body.match(/Sindarov[^}]{0,120}rating\\?"?:(\d{4})/)?.[1] ?? ratingsDoc.body.match(/shortName\\?\\?"Sindarov\\?\\?"[^}]{0,80}rating\\?"?:(\d{4})/)?.[1], "Sindarov rating");
  const ratingB = requireNum(ratingsDoc.body.match(/shortName\\?\\?"Gukesh\\?\\?"[^}]{0,80}rating\\?"?:(\d{4})/)?.[1], "Gukesh rating");

  const targetGame = Number(seed.market.targetGame ?? 8);
  const gamesRemaining = Math.max(targetGame - gamesPlayed, 0);
  const drawShare = Number(seed.assumptions.drawShare);

  const figures = [
    `FIDE official factsheet (fide.com/new-documents, fetched ${ctx.now.toISOString().slice(0, 10)}): game ${gamesPlayed} ended ${whiteName} (White) vs ${blackName} (Black) with result ½-½; match score ${scoreA}-${scoreB}`,
    `Elo ratings of the two players (worldchess.com event metadata, live pages): Sindarov ${ratingA} (UZB) vs Gukesh ${ratingB} (IND) — a ${ratingA - ratingB} Elo gap`,
    `Color allocation so far: Sindarov held White in games 1 and 3 (stated in the factsheet's game-3 preview: "white pieces for the second time in the match tomorrow, when game ${nextWhiteM?.[1] ?? 3}")`,
    `Model: exact enumeration of the ${gamesRemaining} remaining games (to the market's after-game-${targetGame} evaluation) with per-game W/D/L derived from the live Elo gap and a stated ${(drawShare * 100).toFixed(0)}% draw-share assumption, color-averaged`,
  ];
  const headline =
    `After game ${gamesPlayed} of the FIDE World Chess Championship 2026 the official match score is ${scoreA}-${scoreB} (both games drawn), and the challenger Sindarov — rated ${ratingA} vs Gukesh's ${ratingB} — ` +
    `holds a ${gamesRemaining > 0 ? `${gamesRemaining}-game` : ""} stretch before the market's after-game-${targetGame} evaluation point in which an exact enumeration of Elo-implied outcomes puts him ` +
    `ahead with the probability computed in the attached CSV.`;

  const links: SourceLink[] = [
    {
      url: fideDoc.url,
      label: "FIDE official documents page: WCC 2026 game factsheets (result, colors, match score)",
      lang: "en",
      access: "scraped",
      expect: [scoreM[0].slice(0, 20)],
    },
    {
      url: ratingsDoc.url,
      label: "World Chess event page (player ratings + schedule metadata)",
      lang: "en",
      access: "scraped",
      expect: [String(ratingA), String(ratingB)],
    },
  ];
  return assemble(
    seed,
    [fideDoc, ratingsDoc],
    headline,
    figures,
    [
      `fide.com/new-documents (static): FACT SHEET Game ${gameM[1]} — White ${whiteM[1]}, Black ${blackM[1]}, result ½-½, match score ${scoreA}-${scoreB}.`,
      `worldchess.com event page (static): embedded player metadata — Sindarov rated ${ratingA}, Gukesh rated ${ratingB}.`,
    ],
    links,
    {
      kind: "match_lead_elo",
      params: {
        nameA: "Sindarov",
        nameB: "Gukesh",
        scoreA,
        scoreB,
        eloA: ratingA,
        eloB: ratingB,
        gamesRemaining,
        drawShare,
        scoreSource: "fide.com/new-documents factsheet",
        eloSource: "worldchess.com event metadata",
      },
    },
    [
      `Draw-share assumption (${(drawShare * 100).toFixed(0)}%, color-averaged) is a stated model input, not a fetched figure`,
    ],
  );
}

/** Path 2: English Wikipedia article count — siteinfo + Size-of-Wikipedia table. */
export async function refreshWikipedia(seed: SeedInput, api: SourceApi, ctx: RefreshCtx): Promise<Refreshed> {
  const [apiDoc, sizeDoc] = await Promise.all([
    fresh(api, seed.sources.siteinfoApi, "siteinfoApi", ctx),
    fresh(api, seed.sources.sizePage, "sizePage", ctx),
  ]);
  const articles = (apiDoc.json as { query?: { statistics?: { articles?: number } } })?.query?.statistics?.articles;
  if (!articles || articles < 1_000_000) throw new LiveMiningError("siteinfo articles count missing");
  const yearStartM = sizeDoc.body.match(/2026-01-01\s*\n+\s*([\d.,]+)/);
  const netYtdM = sizeDoc.body.match(/7,[\d,]{2,}\s*\n?\s*([\d,]{3,7})\s*\n/);
  if (!yearStartM) throw new LiveMiningError("Size-of-Wikipedia year-start row did not parse");
  const yearStart = Number(yearStartM[1].replace(/[.,]/g, ""));
  const netYtd = articles - yearStart;
  if (netYtd < 0) throw new LiveMiningError("siteinfo count below year-start count — inconsistent fetches");

  const target = Number(seed.market.targetCount);
  const cutoffAt = String(seed.market.cutoffAt);
  const daysRemaining = Math.max((new Date(cutoffAt).getTime() - ctx.now.getTime()) / 86_400_000, 0.1);
  const daysElapsed = (ctx.now.getTime() - new Date(new Date(ctx.now).getFullYear(), 0, 1).getTime()) / 86_400_000;
  const dailyNetMean = netYtd / daysElapsed;
  const dailyNetSd = Number(seed.assumptions.dailyNetSd);

  const required = target - articles;
  const requiredPerDay = required / daysRemaining;

  const figures = [
    `English Wikipedia siteinfo API (fetched live, timestamp in the CSV): ${articles.toLocaleString("en-US")} articles`,
    `Net growth so far this year (live "Size of Wikipedia" table): +${netYtd.toLocaleString("en-US")} since the 2026-01-01 value of ${yearStart.toLocaleString("en-US")} — ~${dailyNetMean.toFixed(1)}/day`,
    `Required net to reach ${target.toLocaleString("en-US")} by ${cutoffAt.slice(0, 16).replace("T", " ")} UTC: +${required.toLocaleString("en-US")} = ${requiredPerDay.toFixed(1)}/day over the ${daysRemaining.toFixed(1)} days left`,
    requiredPerDay <= dailyNetMean
      ? `The required pace (${requiredPerDay.toFixed(0)}/day) is BELOW the live observed pace (${dailyNetMean.toFixed(0)}/day)`
      : `The required pace (${requiredPerDay.toFixed(0)}/day) is ABOVE the live observed pace (${dailyNetMean.toFixed(0)}/day)`,
  ];
  const headline =
    `Live siteinfo + the Size-of-Wikipedia growth table (fetched ${ctx.now.toISOString().slice(0, 10)}) put English Wikipedia at ` +
    `${articles.toLocaleString("en-US")} articles with a net creation pace of ~${dailyNetMean.toFixed(0)}/day this year; reaching ${target.toLocaleString("en-US")} by the market's check time needs ` +
    `${requiredPerDay.toFixed(0)}/day — ${requiredPerDay <= dailyNetMean ? "a pace the current velocity is already beating" : "a faster pace than observed"}.`;

  const links: SourceLink[] = [
    {
      url: apiDoc.url,
      label: "English Wikipedia siteinfo statistics API (live article count)",
      lang: "en",
      access: "api-json",
      expect: [String(articles)],
    },
    {
      url: sizeDoc.url,
      label: "Wikipedia:Size of Wikipedia (growth table: year-start and year-to-date net)",
      lang: "en",
      access: "scraped",
      expect: [yearStartM[1]],
    },
  ];
  return assemble(
    seed,
    [apiDoc, sizeDoc],
    headline,
    figures,
    [
      `siteinfo API (JSON): articles = ${articles}.`,
      `Wikipedia:Size of Wikipedia (static): 2026-01-01 row = ${yearStart.toLocaleString("en-US")}; net growth this year = ${(netYtd / 1000).toFixed(0)}k (cross-checked against the live siteinfo count).`,
    ],
    links,
    {
      kind: "threshold_velocity",
      params: {
        currentCount: articles,
        targetCount: target,
        daysRemaining: Number(daysRemaining.toFixed(2)),
        dailyNetMean: Number(dailyNetMean.toFixed(1)),
        dailyNetSd,
        velocity: {
          label: `${new Date(ctx.now).getFullYear()} year-to-date`,
          days: Number(daysElapsed.toFixed(0)),
          net: netYtd,
        },
      },
    },
    [`Daily net-creation sd (${dailyNetSd}/day) is a stated model assumption`],
  );
}

interface TagDate {
  tag: string;
  published: string;
}

/** Shared: release-gap CDF from a live releases JSON endpoint. */
async function releasesGapCdf(
  seed: SeedInput,
  api: SourceApi,
  ctx: RefreshCtx,
  opts: {
    sourceKey: string;
    kindLabel: string;
    windowStart: string;
    windowEnd: string;
    filterTags?: (tags: TagDate[]) => TagDate[];
    extraFigures?: string[];
    docs2?: Promise<SourceDoc[]>;
  },
): Promise<Refreshed> {
  const [relDoc, ...extraDocs] = await Promise.all([
    fresh(api, seed.sources[opts.sourceKey], opts.sourceKey, ctx),
    ...(opts.docs2 ? opts.docs2 : []),
  ]);
  const releasesRaw = relDoc.json as unknown;
  if (!Array.isArray(releasesRaw)) throw new LiveMiningError(`${opts.kindLabel} endpoint did not return a JSON array`);
  const tags = (releasesRaw as { tag_name?: string; published_at?: string }[])
    .map((r) => ({ tag: r.tag_name ?? "", published: r.published_at ?? "" }))
    .filter((r) => r.tag && r.published);
  const releases = (opts.filterTags ? opts.filterTags(tags) : tags).map((t) => ({ tag: t.tag, date: t.published.slice(0, 10) }));
  if (releases.length < 4) throw new LiveMiningError(`${opts.kindLabel}: fewer than 4 releases parsed`);

  const linkMain: SourceLink = {
    url: relDoc.url,
    label: String(seed.sources[opts.sourceKey].label),
    lang: "en",
    access: "api-json",
    expect: [releases[releases.length - 1].tag],
  };
  const links = extraDocs.length > 0 ? [linkMain, seed.sources[Object.keys(seed.sources).find((k) => seed.sources[k].url === extraDocs[0]?.url) ?? ""] ?? linkMain] : [linkMain];

  const figures = [
    ...opts.extraFigures?.map((t) => t) ?? [],
    `Last ${releases.length} ${opts.kindLabel} releases (live from the API): ${releases.map((r) => `${r.tag} @ ${r.date}`).join("; ")}`,
    `Next release lands in the market window [${opts.windowStart}..${opts.windowEnd}] — computed by the empirical gap distribution over those live dates`,
  ];
  const headline =
    `Live ${opts.kindLabel} release history (fetched ${ctx.now.toISOString().slice(0, 10)}, full list in the CSV) gives an empirical release-gap ` +
    `distribution; the market window [${opts.windowStart}..${opts.windowEnd}] is scored against exactly those gaps.`;
  return assemble(
    seed,
    [relDoc, ...extraDocs],
    headline,
    figures,
    [`${opts.kindLabel} releases API (JSON): publish dates of the ${releases.length} most recent releases; parsed live in this run.`],
    links,
    {
      kind: "release_gap_cdf",
      params: {
        releases,
        windowStart: opts.windowStart,
        windowEnd: opts.windowEnd,
      },
    },
    [],
  );
}

/** Path 2: Bun release timing. */
export async function refreshBunReleases(seed: SeedInput, api: SourceApi, ctx: RefreshCtx): Promise<Refreshed> {
  return releasesGapCdf(seed, api, ctx, {
    sourceKey: "bunApi",
    kindLabel: "oven-sh/bun",
    windowStart: String(seed.market.windowStart),
    windowEnd: String(seed.market.windowEnd),
  });
}

/** Path 2: Go minor release listing (go.dev) + Go1.27.5 milestone by TITLE. */
export async function refreshGoRelease(seed: SeedInput, api: SourceApi, ctx: RefreshCtx): Promise<Refreshed> {
  const [relDoc] = await Promise.all([fresh(api, seed.sources.goDevel, "goDevel", ctx)]);

  // Milestone by TITLE: walk pages until the exact title matches.
  const wantedTitle = String(seed.market.milestoneTitle);
  let milestone: { number: number; title: string; open_issues: number; closed_issues: number } | undefined;
  for (let page = 1; page <= 10 && !milestone; page++) {
    const url = String(seed.market.milestonesUrl).replace("{page}", String(page));
    let doc: SourceDoc;
    try {
      doc = await api.fetch(url);
    } catch (err) {
      throw new LiveMiningError(`milestone search fetch failed (page ${page}): ${(err as Error).message}`);
    }
    if (ctx.live) assertFresh(doc, ctx.now);
    const arr = doc.json as { number: number; title: string; open_issues: number; closed_issues: number }[];
    if (!Array.isArray(arr) || arr.length === 0) break;
    milestone = arr.find((m) => m.title === wantedTitle);
  }
  if (!milestone) throw new LiveMiningError(`milestone "${wantedTitle}" not found by title in the GitHub API`);
  // Explicit guard: an ID picked by title must never silently mismatch (old bug: #305 = Go1.20.4).
  if (milestone.title !== wantedTitle) throw new LiveMiningError("milestone title mismatch — refusing");

  const minorRe = new RegExp(`${String(seed.market.minorPrefix)}(\\d+)\\s*\\(released (\\d{4}-\\d{2}-\\d{2})\\)`, "g");
  const releases: { tag: string; date: string }[] = [];
  for (const m of relDoc.body.matchAll(minorRe)) {
    releases.push({ tag: `${seed.market.minorPrefix}${m[1]}`, date: m[2] });
  }
  if (releases.length < 3) throw new LiveMiningError("go.dev minor releases did not parse");
  releases.sort((a, b) => a.date.localeCompare(b.date));

  const windowStart = ctx.now.toISOString().slice(0, 10);
  const windowEnd = String(seed.market.windowEnd);
  const gaps = releases.slice(1).map((r, i) => ({ from: releases[i].tag, to: r.tag, days: (new Date(r.date).getTime() - new Date(releases[i].date).getTime()) / 86_400_000 }));

  const figures = [
    `Go1.27.5 milestone found BY TITLE via the GitHub API: number ${milestone.number}, state open, ${milestone.open_issues} open / ${milestone.closed_issues} closed issues (note: milestone number is never hardcoded — it is looked up by title every run)`,
    `go.dev release history (live): ${releases.map((r) => `${r.tag} (${r.date})`).join(", ")} — gaps ${gaps.map((g) => `${g.days.toFixed(0)}d`).join(", ")}`,
    `${milestone.open_issues} open blockers on the milestone at fetch; the window for go1.27.5 to appear on go.dev is [${windowStart}..${windowEnd}]`,
  ];
  const headline =
    `go.dev lists ${releases[releases.length - 1].tag} as the newest ${seed.market.minorPrefix}x minor (released ${releases[releases.length - 1].date}), and the Go1.27.5 milestone ` +
    `(looked up by title, number ${milestone.number}) still shows ${milestone.open_issues} open blockers; the live minor-release gap distribution ` +
    `(${gaps.map((g) => g.days.toFixed(0)).join("/")} days) is scored against the listing window [${windowStart}..${windowEnd}] in the CSV.`;

  const links: SourceLink[] = [
    {
      url: relDoc.url,
      label: "go.dev/doc/devel/release (release history)",
      lang: "en",
      access: "scraped",
      expect: [releases[releases.length - 1].date],
    },
  ];
  return assemble(
    seed,
    [relDoc],
    headline,
    figures,
    [
      `go.dev release history (static): parsed live in this run.`,
      `GitHub milestones API: searched by exact title "${wantedTitle}" (hit: number ${milestone.number}); never a hardcoded milestone ID.`,
    ],
    links,
    {
      kind: "release_gap_cdf",
      params: { releases, windowStart, windowEnd },
    },
    [`Empirical gap distribution has only ${gaps.length + 0 || gaps.length} observations — small-sample caveat stated`],
  );
}

/** Path 2 (calculator coverage): Node.js dist releases — used for the Node market when eligible. */
export async function refreshNodeReleases(seed: SeedInput, api: SourceApi, ctx: RefreshCtx): Promise<Refreshed> {
  return releasesGapCdf(seed, api, ctx, {
    sourceKey: "nodeDist",
    kindLabel: "nodejs.org/dist",
    windowStart: ctx.now.toISOString().slice(0, 10),
    windowEnd: String(seed.market.windowEnd),
    filterTags: (tags) => {
      const versions = tags.map((t) => ({ ...t, version: t.tag.replace(/^v/, "") }));
      const line = versions.filter((v) => v.version.startsWith(String(seed.market.versionLine) + "."));
      return line.length >= 4 ? line : versions.filter((v) => /^v\d+(\.\d+)*$/.test(v.tag)).slice(0, 10);
    },
  });
}

